#define t iTime * .03//
#define C(a, e) cross(a - d, e - d).z//
#define F(a, e) C(u, e) * C(a, e) > 0. ?//
#define move (exp(tanh(cos(iTime * .23) * 5. + 3.)) / 19. + .01)

void mainImage(out vec4 o, vec2 U) {
    vec3 u, a, b, c, d, e, 
         r = iResolution,
         G = a + .618;
         u.xy = (U - r.xy / 2.) / r.y // camera
                 * move
                 + vec2(
                       cos(t / 2.) + 2. * cos(t) + 3.3,
                       sin(t / 2.) - 2. * sin(t)
                   ) * vec2(.3, .2)
                 ;

    int i, T;
    b.y = 1.;
    a = -b;

    // penrose Kite & Dart
    // https://www.shadertoy.com/view/M3cBzl
    for(c.x = 3.08; i++ < 13;){
        d = c + (b - c) * G;
        if(T < 1)
            e = a + (c - a) * G,
            F(c, e) 
                  T++, a = e
                : F(b, a) 
                         c = a, a = b 
                      : (c = a, a = e),
                      b = d; 
        else 
            G.z += float(i % 2 * 2 - 1),
            F(c, a)
                    T--,        b = a, a = d
                  :     (c = b, b = a, a = d);

    }


    o = mix(
            // colors(G.z)
            vec4(.6), 
            vec4(
                mod(G.z + 3., 3.) < 2., 
                G.z > 0.,
                mod(G.z + 3., 3.) < 1., 0
            ),

            // shape(T, a, b)
            smoothstep(
                 .1 / iResolution.y, .0, 
                     abs(
                         length(u - (T>0?a:b)) - (T<1?.0023:.0015)) - 5e-4
            )
        );
}
